SELECT current_database(),current_setting('default_transaction_read_only'),clock_timestamp();
WITH scopes AS (SELECT id,tenant_id,owner_user_id,'W'||dense_rank() OVER (ORDER BY id) AS w,'T'||dense_rank() OVER (ORDER BY tenant_id) AS t FROM workspaces)
SELECT s.t,s.w,m.role,count(*) AS memberships FROM scopes s JOIN workspace_memberships m ON m.workspace_id=s.id WHERE s.id IN (SELECT workspace_id FROM context_documents UNION SELECT workspace_id FROM job_queue UNION SELECT workspace_id FROM chat_sessions) GROUP BY 1,2,3 ORDER BY 1,2,3;
WITH scopes AS (SELECT id,tenant_id,owner_user_id,'W'||dense_rank() OVER (ORDER BY id) AS w,'T'||dense_rank() OVER (ORDER BY tenant_id) AS t FROM workspaces)
SELECT s.t,s.w,count(*) AS messages,count(*) FILTER (WHERE c.id IS NULL OR s.id IS NULL) AS missing_scope,count(*) FILTER (WHERE u.id IS NULL) AS missing_user,count(*) FILTER (WHERE c.user_id=s.owner_user_id) AS owner_messages,count(*) FILTER (WHERE EXISTS(SELECT 1 FROM workspace_memberships m WHERE m.workspace_id=s.id AND m.user_id=c.user_id)) AS member_messages FROM chat_messages msg LEFT JOIN chat_sessions c ON c.id=msg.session_id LEFT JOIN scopes s ON s.id=c.workspace_id LEFT JOIN users u ON u.id=c.user_id GROUP BY 1,2 ORDER BY 1,2;
SELECT count(*) AS documents,count(*) FILTER (WHERE w.id IS NULL OR w.tenant_id IS NULL) AS missing_scope,count(*) FILTER (WHERE u.id IS NULL) AS missing_owner FROM context_documents d LEFT JOIN workspaces w ON w.id=d.workspace_id LEFT JOIN users u ON u.id=w.owner_user_id;
